    98→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID string, state *SessionState) (*CondenseResult, error) {
    99→	// Get shadow branch
   100→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
